public class BackgroundProcessor
{
    private readonly IServiceProvider _services;

    public BackgroundProcessor(IServiceProvider services)
    {
        _services = services;
    }

    public async Task ProcessAsync()
    {
        using var scope = _services.CreateScope();
        var repo = scope.ServiceProvider.GetRequiredService<IRepository>();
        await repo.DoWorkAsync();
    }
}

// Base interface
public interface IUserService
{
    Task<User> GetUserAsync(int id);
}

// Base implementation
public class UserService : IUserService
{
    private readonly IUserRepository _repo;

    public UserService(IUserRepository repo)
    {
        _repo = repo;
    }

    public async Task<User> GetUserAsync(int id)
    {
        return await _repo.GetByIdAsync(id);
    }
}

// Caching decorator
public class CachedUserService : IUserService
{
    private readonly IUserService _inner;
    private readonly IMemoryCache _cache;

    public CachedUserService(IUserService inner, IMemoryCache cache)
    {
        _inner = inner;
        _cache = cache;
    }

    public async Task<User> GetUserAsync(int id)
    {
        string key = $"user:{id}";
        return await _cache.GetOrCreateAsync(key, async entry =>
        {
            entry.AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(5);
            return await _inner.GetUserAsync(id);
        });
    }
}

// Logging decorator
public class LoggingUserService : IUserService
{
    private readonly IUserService _inner;
    private readonly ILogger<LoggingUserService> _logger;

    public LoggingUserService(IUserService inner, ILogger<LoggingUserService> logger)
    {
        _inner = inner;
        _logger = logger;
    }

    public async Task<User> GetUserAsync(int id)
    {
        _logger.LogInformation("Getting user {UserId}", id);
        try
        {
            var user = await _inner.GetUserAsync(id);
            _logger.LogInformation("Got user {UserId}", id);
            return user;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to get user {UserId}", id);
            throw;
        }
    }
}

// Registration with decorators
builder.Services.AddTransient<IUserService, UserService>();
builder.Services.Decorate<IUserService, CachedUserService>();
builder.Services.Decorate<IUserService, LoggingUserService>();

// Define factory interface
public interface IReportGeneratorFactory
{
    IReportGenerator Create(ReportType type);
}

// Implementation
public class ReportGeneratorFactory : IReportGeneratorFactory
{
    private readonly IServiceProvider _services;

    public ReportGeneratorFactory(IServiceProvider services)
    {
        _services = services;
    }

    public IReportGenerator Create(ReportType type)
    {
        return type switch
        {
            ReportType.Pdf => _services.GetRequiredService<PdfReportGenerator>(),
            ReportType.Excel => _services.GetRequiredService<ExcelReportGenerator>(),
            _ => throw new ArgumentException($"Unknown report type: {type}")
        };
    }
}

// Usage
public class ReportService
{
    private readonly IReportGeneratorFactory _factory;

    public ReportService(IReportGeneratorFactory factory)
    {
        _factory = factory;
    }

    public async Task GenerateReportAsync(ReportType type, ReportData data)
    {
        var generator = _factory.Create(type);
        await generator.GenerateAsync(data);
    }
}

[Test]
public async Task GetUserAsync_WhenUserExists_ReturnsUser()
{
    // Arrange
    var mockRepo = new Mock<IUserRepository>();
    var expectedUser = new User { Id = 1, Name = "Test" };
    mockRepo.Setup(r => r.GetByIdAsync(1)).ReturnsAsync(expectedUser);

    var service = new UserService(mockRepo.Object);

    // Act
    var result = await service.GetUserAsync(1);

    // Assert
    Assert.AreEqual(expectedUser, result);
    mockRepo.Verify(r => r.GetByIdAsync(1), Times.Once);
}

